# kijk op number theory slides (homework)

def chinese_remainder_theorem(n, a):
    total = 0
    prod = 1
    for ni in n:
        prod *= ni

    for ni, ai in zip(n, a):
        p = prod // ni
        total += ai * pow(p, -1, ni) * p
    return total % prod
